package tls

// [uTLS] The fixtures crypto/tls's tests used before Go 1.26 regenerated
// them (internal/testcerts), which the fork's own tests are written against:
// testConfig as handshake_test.go's TestMain made it, and the keys and
// certificates it and they name, as they were.

import (
	"crypto/x509"
	"time"
)

var testConfig *Config

func init() {
	testConfig = &Config{
		Time:               func() time.Time { return time.Unix(0, 0) },
		Rand:               zeroSource{},
		Certificates:       make([]Certificate, 2),
		InsecureSkipVerify: true,
		CipherSuites:       allCipherSuites(),
		CurvePreferences:   []CurveID{X25519, CurveP256, CurveP384, CurveP521},
		MinVersion:         VersionTLS10,
		MaxVersion:         VersionTLS13,
	}
	testConfig.Certificates[0].Certificate = [][]byte{testRSACertificate}
	testConfig.Certificates[0].PrivateKey = testRSAPrivateKey
	testConfig.Certificates[1].Certificate = [][]byte{testSNICertificate}
	testConfig.Certificates[1].PrivateKey = testRSAPrivateKey
	testConfig.BuildNameToCertificate()
}

var testRSACertificate = fromHex("")

var testSNICertificate = fromHex("")

var testP256Certificate = fromHex("")

var testRSA2048PrivateKey, _ = x509.ParsePKCS1PrivateKey(fromHex(""))

var testRSAPrivateKey, _ = x509.ParsePKCS1PrivateKey(fromHex(""))

var testECDSAPrivateKey, _ = x509.ParseECPrivateKey(fromHex(""))

var testP256PrivateKey, _ = x509.ParseECPrivateKey(fromHex("30770201010420012f3b52bc54c36ba3577ad45034e2e8efe1e6999851284cb848725cfe029991a00a06082a8648ce3d030107a14403420004c02c61c9b16283bbcc14956d886d79b358aa614596975f78cece787146abf74c2d5dc578c0992b4f3c631373479ebf3892efe53d21c4f4f1cc9a11c3536b7f75"))

func allCipherSuites() []uint16 {
	ids := make([]uint16, len(cipherSuites))
	for i, suite := range cipherSuites {
		ids[i] = suite.id
	}

	return ids
}
